import java.nio.file.*;
import java.util.*;
import java.util.jar.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import com.google.gson.*;

/** Adds explicitly conditional analysis variants without redirecting runtime callers. */
public class ApplyInferredProfiles {
 static int argumentSlots(MethodNode m){int n=(m.access&Opcodes.ACC_STATIC)!=0?0:1;for(Type t:Type.getArgumentTypes(m.desc))n+=t.getSize();return n;}
 static void shiftConstructorTemps(MethodNode m,int boundary,int extra){
  for(AbstractInsnNode n:m.instructions){if(n instanceof VarInsnNode v&&v.var>=boundary)v.var+=extra;if(n instanceof IincInsnNode i&&i.var>=boundary)i.var+=extra;if(n instanceof FrameNode f&&f.local!=null){if(f.type!=Opcodes.F_NEW)throw new IllegalArgumentException("Expanded frames required");int slot=0;for(int i=0;i<f.local.size();i++){if(slot==boundary){for(int j=0;j<extra;j++)f.local.add(i,Opcodes.TOP);break;}Object v=f.local.get(i);slot+=v.equals(Opcodes.LONG)||v.equals(Opcodes.DOUBLE)?2:1;}}}
  if(m.localVariables!=null)for(LocalVariableNode v:m.localVariables)if(v.index>=boundary)v.index+=extra;
  for(List<LocalVariableAnnotationNode> annotations:Arrays.asList(m.visibleLocalVariableAnnotations,m.invisibleLocalVariableAnnotations))if(annotations!=null)for(LocalVariableAnnotationNode a:annotations)for(int i=0;i<a.index.size();i++)if(a.index.get(i)>=boundary)a.index.set(i,a.index.get(i)+extra);
  m.maxLocals+=extra;
 }
 public static void main(String[] args)throws Exception{
  Map<String,byte[]> entries=new LinkedHashMap<>();Map<String,ClassNode> classes=new LinkedHashMap<>();try(JarFile jar=new JarFile(args[0])){for(JarEntry e:Collections.list(jar.entries()))if(!e.isDirectory()){byte[] b=jar.getInputStream(e).readAllBytes();entries.put(e.getName(),b);if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,ClassReader.EXPAND_FRAMES);classes.put(c.name,c);}}}
  Map<String,Object> constants=SpecializeKeys.constants(classes);List<Map<String,Object>> report=new ArrayList<>();Set<String> changed=new HashSet<>();int methods=0,constructors=0,fieldLoads=0,skipped=0;
  for(JsonElement element:JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonArray()){
   JsonObject p=element.getAsJsonObject();ClassNode c=classes.get(p.get("owner").getAsString());String name=p.get("name").getAsString(),desc=p.get("descriptor").getAsString();MethodNode original=c.methods.stream().filter(m->m.name.equals(name)&&m.desc.equals(desc)).findFirst().orElseThrow();if(original.instructions.size()>12000){skipped++;continue;}Map<String,Long> bindings=new LinkedHashMap<>();for(var e:p.getAsJsonObject("bindings").entrySet())bindings.put(e.getKey(),e.getValue().getAsLong());boolean constructor=name.equals("<init>");
   Frame<RestoreStrings.V>[] frames=new Analyzer<>(new InferReferenceKeys.Symbolic(constants,classes)).analyze(c.name,original);MethodNode clone=SpecializeKeys.copy(original);clone.access&=~(Opcodes.ACC_SYNTHETIC|Opcodes.ACC_BRIDGE);clone.visibleAnnotations=null;clone.invisibleAnnotations=null;AbstractInsnNode[] nodes=clone.instructions.toArray();InferReferenceKeys.Symbolic symbolic=new InferReferenceKeys.Symbolic(constants,classes);
   if(!constructor)for(int i=0;i<nodes.length;i++)if(nodes[i] instanceof FieldInsnNode f&&f.getOpcode()==Opcodes.GETFIELD&&frames[i]!=null&&frames[i].getStackSize()>0&&frames[i].getStack(frames[i].getStackSize()-1).value==InferReferenceKeys.This.VALUE){String symbol=symbolic.field(f);if(symbol!=null&&bindings.containsKey(symbol)){InsnList replacement=new InsnList();replacement.add(new InsnNode(Opcodes.POP));replacement.add(new LdcInsnNode(bindings.get(symbol)));clone.instructions.insertBefore(f,replacement);clone.instructions.remove(f);fieldLoads++;}}
   if(constructor){int extra=1;String revised=desc.substring(0,desc.indexOf(')'))+"Z)"+Type.getReturnType(desc).getDescriptor();while(true){String candidate=revised;if(c.methods.stream().noneMatch(m->m.name.equals("<init>")&&m.desc.equals(candidate)))break;extra++;revised=desc.substring(0,desc.indexOf(')'))+"Z".repeat(extra)+")V";}shiftConstructorTemps(clone,argumentSlots(original),extra);clone.desc=revised;clone.access&=~Opcodes.ACC_VARARGS;clone.visibleParameterAnnotations=null;clone.invisibleParameterAnnotations=null;clone.visibleAnnotableParameterCount=0;clone.invisibleAnnotableParameterCount=0;clone.parameters=new ArrayList<>();for(int i=0;i<Type.getArgumentTypes(desc).length;i++)clone.parameters.add(new ParameterNode(original.parameters!=null&&i<original.parameters.size()?original.parameters.get(i).name:null,0));for(int i=0;i<extra;i++)clone.parameters.add(new ParameterNode("inferredContext"+i,0));if(clone.signature!=null){int at=clone.signature.lastIndexOf(')');clone.signature=clone.signature.substring(0,at)+"Z".repeat(extra)+clone.signature.substring(at);}constructors++;}
   else {clone.name=name+"$inferred$"+SpecializeKeys.hash(c.name+'\t'+name+'\t'+desc+'\t'+p.get("bindings"));if(c.methods.stream().anyMatch(m->m.name.equals(clone.name)&&m.desc.equals(clone.desc)))throw new IllegalStateException("Inferred name collision");methods++;}
   InsnList prelude=new InsnList();for(var binding:bindings.entrySet())if(binding.getKey().startsWith("arg:")){int slot=Integer.parseInt(binding.getKey().substring(4));prelude.add(new LdcInsnNode(binding.getValue()));prelude.add(new VarInsnNode(Opcodes.LSTORE,slot));}clone.instructions.insert(prelude);clone.maxStack=Math.max(clone.maxStack,2);new Analyzer<>(new BasicVerifier()).analyze(c.name,clone);c.methods.add(clone);changed.add(c.name);Map<String,Object> row=new LinkedHashMap<>();row.put("owner",c.name);row.put("originalName",name);row.put("originalDescriptor",desc);row.put("variantName",clone.name);row.put("variantDescriptor",clone.desc);row.put("requiredBindings",bindings);row.put("constructorMarkerParameters",constructor?Type.getArgumentTypes(clone.desc).length-Type.getArgumentTypes(desc).length:0);row.put("runtimeCallersRedirected",false);row.put("status","Analysis context: requires the recorded arguments/final instance fields; caller reachability is unproven");report.add(row);
  }
  try(JarOutputStream jar=new JarOutputStream(Files.newOutputStream(Path.of(args[2])))){for(var e:entries.entrySet()){byte[] b=e.getValue();String n=e.getKey();if(n.endsWith(".class")&&changed.contains(n.substring(0,n.length()-6))){ClassWriter writer=new ClassWriter(ClassWriter.COMPUTE_MAXS);classes.get(n.substring(0,n.length()-6)).accept(writer);b=writer.toByteArray();}jar.putNextEntry(new JarEntry(n));jar.write(b);jar.closeEntry();}}
  Files.writeString(Path.of(args[3]),new GsonBuilder().setPrettyPrinting().create().toJson(report));System.out.println("Added inferred methods="+methods+" constructor contexts="+constructors+" final-key field loads specialized="+fieldLoads+" large methods skipped="+skipped+"; runtime callers unchanged");
 }
}
